import React, { useState, useMemo, useCallback, useEffect } from 'react';
import { Loader2, RefreshCw, Users, Compass, UserPlus, Search, Film, BarChart3, Radio, Bookmark, TrendingUp, Sparkles, Calendar, Settings, ShieldCheck, Eye, Flame, ChevronRight, Building2 } from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import PostCard from './social/PostCard';
import CreatePostWidget from './social/CreatePostWidget';
import ReportModal from './ReportModal';
import Discover from './social/Discover';
import StoriesBar from './social/StoriesBar';
import LiveSpacesBar from './social/LiveSpacesBar';
import ReelsFeed from './social/ReelsFeed';
import CommunitiesSection from './social/CommunitiesSection';
import { useFollowSystem } from '../hooks/useFollowSystem';
import FollowButton from './social/FollowButton';
import UserAvatar from './shared/UserAvatar';
import { useLanguage } from '../contexts/LanguageContext';
import { useFeed, useHomeFeed, useStudioPosts, useCreatePost, useUserByClerkId, useActiveSponsoredPosts } from '@/hooks/useConvex';
import { shouldShowAds } from '../utils/tierPermissions';
import SponsoredPostCard from './social/SponsoredPostCard';
import BoostVisibilityModal from './social/BoostVisibilityModal';
import type { UserData } from '../types';

// =====================================================
// TYPES & CONSTANTS
// =====================================================

const FEED_MODES = {
  FOR_YOU: 'for_you',
  FOLLOWING: 'following',
  REELS: 'reels',
  COMMUNITIES: 'communities',
  STUDIO: 'studio',
  DISCOVER: 'discover'
} as const;

type FeedMode = typeof FEED_MODES[keyof typeof FEED_MODES];

interface SocialFeedProps {
  user: {
    id?: string;
    uid?: string;
    username?: string;
    firstName?: string;
    lastName?: string;
    email?: string;
    primaryEmailAddress?: { emailAddress: string };
    emailAddresses?: Array<{ emailAddress: string }>;
    imageUrl?: string;
    profileImageUrl?: string;
    publicMetadata?: {
      username?: string;
      account_types?: string[];
      active_role?: string;
    };
    [key: string]: any;
  };
  userData: UserData | null;
  subProfiles?: Record<string, any>;
  openPublicProfile?: (userId: string) => void;
}

interface Post {
  id: string;
  userId: string;
  displayName: string;
  authorPhoto?: string | null;
  username?: string;
  text?: string;
  attachments?: any[];
  timestamp: string | number;
  commentCount: number;
  reactionCount: number;
  saveCount: number;
  role?: string;
  [key: string]: any;
}

interface SuggestedUser {
  userId: string;
  displayName: string;
  photoURL: string | null;
  role?: string;
}

interface PostPayload {
  text?: string;
  attachments?: Array<{
    type: string;
    url: string;
    thumbnail?: string | null;
    name?: string | null;
    isGif?: boolean;
  }>;
}

// =====================================================
// COMPONENT
// =====================================================

export default function SocialFeed({
  user,
  userData,
  subProfiles = {},
  openPublicProfile
}: SocialFeedProps): JSX.Element {
  const [reportTarget, setReportTarget] = useState<Post | null>(null);
  const [feedMode, setFeedMode] = useState<FeedMode>(FEED_MODES.FOR_YOU);
  const [suggestedUsers, setSuggestedUsers] = useState<SuggestedUser[]>([]);
  const [loadingSuggestions, setLoadingSuggestions] = useState<boolean>(false);

  // Get feed algorithm from settings
  const { t } = useLanguage();
  const settingsObj = (userData?.settings || {}) as any;
  const feedAlgorithm = settingsObj?.social?.feedAlgorithm || 'recommended';
  const autoPlayVideos = settingsObj?.social?.autoPlayVideos !== false;
  const showSuggestedAccounts = settingsObj?.social?.showSuggestedAccounts !== false;

  // Use the follow system hook
  const userId = user?.id || user?.uid;
  const {
    following,
    stats,
    loading: followLoading,
    isFollowing,
    toggleFollow,
    getFollowingIds
  } = useFollowSystem(userId);

  // Memoize following IDs for feed filtering
  const followingIds = useMemo(() => getFollowingIds(), [following]);

  // Get current user from Convex
  const convexUser = useUserByClerkId(userId || '');

  // Ad eligibility and active campaigns
  const isAdEligible = shouldShowAds(userData);
  const activeAds = useActiveSponsoredPosts(userData?.subscriptionTier || 'free') || [];
  const [showBoostModal, setShowBoostModal] = useState<boolean>(false);

  // Get posts based on feed mode
  const feedPosts = useFeed(20); // For You mode
  const homeFeedPosts = useHomeFeed(userId || '', 20); // Following mode (personalized)
  const studioPosts = useStudioPosts(20); // Studio feed mode

  // Select appropriate data source based on feed mode
  const rawPosts = feedMode === FEED_MODES.FOLLOWING
    ? homeFeedPosts
    : feedMode === FEED_MODES.STUDIO
    ? studioPosts
    : feedPosts;

  // Detect media type from URL extension
  const detectMediaType = (url: string): 'image' | 'video' | 'audio' => {
    const path = url.split('?')[0].toLowerCase();
    if (/\.(mp4|webm|mov|avi|mkv|m4v)(\/|$)/i.test(path) || path.includes('video')) return 'video';
    if (/\.(mp3|wav|ogg|aac|flac|m4a|wma)(\/|$)/i.test(path) || path.includes('audio')) return 'audio';
    return 'image';
  };

  // Process posts and map to expected format
  const posts = useMemo(() => {
    if (!rawPosts) return []; // Loading
    if (rawPosts === null) return []; // Error

    // DEBUG: Log first raw Convex post to inspect media fields
    if (rawPosts.length > 0) {
      const sample = rawPosts[0];
      console.log('[SocialFeed DEBUG] Raw Convex post sample:', {
        _id: sample._id,
        content: sample.content?.substring(0, 60),
        mediaUrls: sample.mediaUrls,
        mediaAttachments: sample.mediaAttachments,
        mediaType: sample.mediaType,
      });
    }

    return rawPosts.map((post: any): Post => {
      // mediaAttachments stores structured {url, type} objects (new posts)
      // mediaUrls stores plain strings (legacy posts)
      const attachments = post.mediaAttachments?.length > 0
        ? post.mediaAttachments.map((att: any, idx: number) => ({
            type: att.type || detectMediaType(att.url),
            url: att.url,
            thumbnail: att.url,
            name: att.name || `Attachment ${idx + 1}`,
            isGif: false
          }))
        : post.mediaUrls?.map((url: string, idx: number) => ({
            type: detectMediaType(url),
            url: url,
            thumbnail: url,
            name: `Attachment ${idx + 1}`,
            isGif: false
          }));

      return {
        ...post,
        id: post._id,
        userId: post.authorId,
        authorClerkId: post.authorClerkId,
        displayName: post.displayName || post.authorName || '[Deleted User]',
        authorPhoto: post.authorPhoto || null,
        username: post.username || post.authorUsername,
        text: post.content || post.text,
        attachments,
        timestamp: post.createdAt,
        commentCount: post.engagement?.commentsCount ?? post.commentCount ?? 0,
        reactionCount: post.engagement?.likesCount ?? post.reactionCount ?? 0,
        saveCount: post.engagement?.savesCount ?? post.saveCount ?? 0,
        role: post.role,
        repostOf: post.repostOf,
        originalPost: post.originalPost,
        amendments: post.amendments,
        isEdited: post.isEdited,
      };
    });
  }, [rawPosts]);

  // Combined loading state
  const loading = !rawPosts || followLoading;

  // Load suggested users when on Following tab with no follows
  useEffect(() => {
    const clerkId = user?.id || user?.uid;
    if (feedMode === FEED_MODES.FOLLOWING && followingIds.length === 0 && clerkId) {
      loadSuggestedUsers();
    }
  }, [feedMode, followingIds.length, user?.id, user?.uid]);

  const loadSuggestedUsers = async (): Promise<void> => {
    setLoadingSuggestions(true);
    try {
      const clerkId = user?.id || user?.uid;
      if (!clerkId) return;

      // Get recent posts from users they don't follow
      const recentPosts = feedPosts || [];

      // Filter to get unique user IDs from posts (not current user, not already following)
      const currentUserId = clerkId;
      const followingIdSet = new Set(followingIds);
      followingIdSet.add(currentUserId);

      const uniqueUserIds = [...new Set(
        recentPosts
          .filter((post: any) => !followingIdSet.has(post.authorId))
          .map((post: any) => post.authorId)
      )].slice(0, 10);

      // Fetch user data for each ID
      const suggestedUsersData: SuggestedUser[] = [];
      for (const uid of uniqueUserIds) {
        try {
          const userData = await fetch(`/api/users/${uid}`).then(r => r.json());
          if (userData && userData.id) {
            suggestedUsersData.push({
              userId: userData.id,
              displayName: userData.displayName || userData.username || 'User',
              photoURL: userData.photoURL || null,
              role: userData.accountTypes?.[0] || 'Fan'
            });
          }
        } catch (e) {
          console.error('Failed to fetch user:', e);
        }
      }

      setSuggestedUsers(suggestedUsersData.slice(0, 5));
    } catch (error) {
      console.error('Error loading suggestions:', error);
    }
    setLoadingSuggestions(false);
  };

  // Skeleton loader for feed
  const renderSkeleton = (): JSX.Element => {
    const skeletonItems = Array.from({ length: 3 });
    return (
      <div className="space-y-4 p-fluid">
        <div className="bg-white dark:bg-[#1f2128] rounded-2xl border border-gray-200 dark:border-gray-700 p-4 animate-pulse">
          <div className="h-10 bg-gray-200 dark:bg-gray-700 rounded-xl w-48 mb-3"></div>
          <div className="h-14 bg-gray-100 dark:bg-gray-800 rounded-xl w-full mb-2"></div>
        </div>
        {skeletonItems.map((_, idx) => (
          <div key={idx} className="bg-white dark:bg-[#1f2128] rounded-2xl border border-gray-200 dark:border-gray-700 p-4 animate-pulse space-y-3">
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 rounded-full bg-gray-200 dark:bg-gray-700"></div>
              <div className="flex-1">
                <div className="h-3.5 w-32 bg-gray-200 dark:bg-gray-700 rounded-full mb-2"></div>
                <div className="h-3 w-20 bg-gray-100 dark:bg-gray-800 rounded-full"></div>
              </div>
            </div>
            <div className="h-3 w-5/6 bg-gray-100 dark:bg-gray-800 rounded-full"></div>
            <div className="h-3 w-2/3 bg-gray-100 dark:bg-gray-800 rounded-full"></div>
            <div className="h-48 bg-gray-100 dark:bg-gray-800 rounded-xl"></div>
            <div className="flex gap-3">
              <div className="h-3 w-16 bg-gray-200 dark:bg-gray-700 rounded-full"></div>
              <div className="h-3 w-12 bg-gray-200 dark:bg-gray-700 rounded-full"></div>
            </div>
          </div>
        ))}
      </div>
    );
  };

  const createPost = useCreatePost();

  const handlePost = async (postPayload: PostPayload): Promise<void> => {
    if (!user) return;
    try {
      const clerkId = user.id || user.uid;
      const activeRole = userData?.activeProfileRole || userData?.accountTypes?.[0] || 'Fan';

      // Get active profile data from MongoDB subprofiles first, then fall back to legacy subProfiles
      const mongoSubprofile = userData?.subprofiles?.[activeRole];
      const legacySubprofile = subProfiles?.[activeRole];
      const activeProfile = mongoSubprofile || legacySubprofile || {};

      // Use display_name from MongoDB structure or displayName from legacy structure
      const displayName = activeProfile?.display_name ||
                         activeProfile?.displayName ||
                         userData?.displayName ||
                         userData?.effectiveDisplayName ||
                         `${userData?.firstName || ''} ${userData?.lastName || ''}`.trim() || null;
      const authorPhoto = activeProfile?.photo_url || userData?.photoURL || user?.imageUrl || null;

      // Process attachments from postPayload — preserve type info
      const attachments = postPayload.attachments || [];
      const mediaAttachments = attachments.map(a => ({
        url: a.url,
        type: a.type || 'image',
        name: a.name || null,
      }));

      // Create post using Convex mutation
      await createPost({
        authorId: clerkId,
        content: postPayload.text || '',
        mediaAttachments: mediaAttachments.length > 0 ? mediaAttachments : undefined,
        visibility: 'public',
        category: activeRole,
        customFields: {
          ...((postPayload as any).taggedStudio ? { taggedStudio: (postPayload as any).taggedStudio } : {}),
          ...((postPayload as any).isBoosted ? { isBoosted: true, boostRadiusMiles: (postPayload as any).boostRadiusMiles } : {}),
        },
      });
    } catch (e) {
      console.error("Failed to post:", e);
      alert("Could not post update. Please try again.");
    }
  };

  const containerVariants = {
    hidden: { opacity: 0 },
    show: {
      opacity: 1,
      transition: { staggerChildren: 0.08 }
    }
  };

  // Suggested user card component
  const SuggestedUserCard = ({ suggestedUser }: { suggestedUser: SuggestedUser }): JSX.Element => (
    <motion.div
      initial={{ opacity: 0, y: 10 }}
      animate={{ opacity: 1, y: 0 }}
      className="flex items-center justify-between p-3 bg-white dark:bg-dark-card rounded-xl border dark:border-gray-700 hover:border-brand-blue/30 transition-all"
    >
      <div
        className="flex items-center gap-3 cursor-pointer flex-1 min-w-0"
        onClick={() => openPublicProfile?.(suggestedUser.userId)}
      >
        <UserAvatar
          src={suggestedUser.photoURL}
          name={suggestedUser.displayName}
          size="md"
        />
        <div className="min-w-0">
          <h4 className="font-bold text-sm dark:text-white truncate hover:text-brand-blue transition">
            {suggestedUser.displayName}
          </h4>
          <p className="text-xs text-gray-500 truncate">{suggestedUser.role}</p>
        </div>
      </div>
      <FollowButton
        isFollowing={isFollowing(suggestedUser.userId)}
        onToggle={() => { toggleFollow(suggestedUser.userId); }}
        size="sm"
        variant="default"
      />
    </motion.div>
  );

  const activeRole = userData?.activeProfileRole || userData?.accountTypes?.[0] || 'Creator';
  const displayName = userData?.displayName || userData?.effectiveDisplayName || user?.firstName || 'Creator';
  const photoUrl = userData?.photoURL || user?.imageUrl;

  return (
    <div className="max-w-7xl mx-auto px-2 sm:px-4 pb-20">
      <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
        
        {/* ===================================================== */}
        {/* LEFT COLUMN: Profile & Hub Shortcuts (LinkedIn Style) */}
        {/* ===================================================== */}
        <div className="hidden lg:block lg:col-span-3 space-y-4">
          {/* User Profile Card Widget */}
          <div className="bg-white dark:bg-dark-card rounded-2xl border dark:border-gray-700 overflow-hidden shadow-sm">
            <div className="h-16 bg-gradient-to-r from-brand-blue via-indigo-600 to-purple-600 relative" />
            <div className="p-4 relative pt-0 text-center">
              <div className="-mt-10 mb-2 flex justify-center">
                <div className="p-1 bg-white dark:bg-dark-card rounded-full shadow-md">
                  <UserAvatar src={photoUrl} name={displayName} size="xl" />
                </div>
              </div>
              <h3 className="font-bold text-base dark:text-white">{displayName}</h3>
              <p className="text-xs text-gray-500 font-medium mb-3">{activeRole}</p>

              {/* Profile Completion Bar */}
              <div className="mb-4 bg-gray-50 dark:bg-gray-800 p-2.5 rounded-xl border dark:border-gray-700 text-left">
                <div className="flex justify-between text-[11px] font-bold text-gray-600 dark:text-gray-400 mb-1">
                  <span>Profile Strength</span>
                  <span className="text-brand-blue">85%</span>
                </div>
                <div className="w-full h-1.5 bg-gray-200 dark:bg-gray-700 rounded-full overflow-hidden">
                  <div className="h-full bg-brand-blue" style={{ width: '85%' }} />
                </div>
              </div>

              {/* Followers & Views Metrics */}
              <div className="grid grid-cols-2 gap-2 border-t border-b dark:border-gray-800 py-3 mb-3 text-xs">
                <div>
                  <span className="block text-gray-400 font-medium">Followers</span>
                  <span className="font-extrabold text-sm dark:text-white">{stats.followersCount || 0}</span>
                </div>
                <div>
                  <span className="block text-gray-400 font-medium">Following</span>
                  <span className="font-extrabold text-sm dark:text-white">{stats.followingCount || 0}</span>
                </div>
              </div>

              {/* Quick Links */}
              <div className="space-y-1 text-left">
                <button
                  onClick={() => setFeedMode(FEED_MODES.STUDIO)}
                  className="w-full flex items-center justify-between p-2 rounded-xl text-xs font-semibold text-gray-700 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-800 transition"
                >
                  <span className="flex items-center gap-2">
                    <BarChart3 size={16} className="text-brand-blue" /> Creator Studio
                  </span>
                  <ChevronRight size={14} className="text-gray-400" />
                </button>

                <button
                  onClick={() => setFeedMode(FEED_MODES.COMMUNITIES)}
                  className="w-full flex items-center justify-between p-2 rounded-xl text-xs font-semibold text-gray-700 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-800 transition"
                >
                  <span className="flex items-center gap-2">
                    <Users size={16} className="text-purple-500" /> Joined Circles
                  </span>
                  <ChevronRight size={14} className="text-gray-400" />
                </button>
              </div>
            </div>
          </div>
        </div>

        {/* ===================================================== */}
        {/* CENTER COLUMN: Main Activity Feed & Composer         */}
        {/* ===================================================== */}
        <div className="col-span-12 lg:col-span-6 space-y-4">
          {/* 24h Stories Bar */}
          <StoriesBar
            user={user}
            userData={userData}
            subProfiles={subProfiles}
            onOpenProfile={openPublicProfile}
          />

          {/* Live Audio Spaces Bar */}
          <LiveSpacesBar
            user={user}
            userSettings={userData?.settings}
          />

          {/* Create Post Widget */}
          <CreatePostWidget
            user={user}
            userData={userData}
            subProfiles={subProfiles}
            onPost={handlePost}
          />

          {/* Sticky Feed Mode Toggle Bar with Seamless Top Coverage & Fade */}
          <div className="sticky -top-4 z-30 pt-4 pb-3 -mt-2 -mx-3 sm:-mx-4 px-3 sm:px-4 bg-gray-50/95 dark:bg-[#1a1d21]/95 backdrop-blur-xl transition-all">
            <div className="grid grid-cols-6 gap-1 sm:gap-1.5 bg-white/90 dark:bg-[#1e2128]/90 backdrop-blur-2xl p-1 sm:p-1.5 rounded-2xl border border-gray-200/80 dark:border-white/[0.08] shadow-lg shadow-black/5 dark:shadow-black/20 w-full">
              <button
                onClick={() => setFeedMode(FEED_MODES.FOR_YOU)}
                className={`flex items-center justify-center gap-1 sm:gap-1.5 px-1.5 sm:px-2.5 py-2 rounded-xl text-[11px] sm:text-xs font-bold transition-all duration-200 w-full min-w-0 ${
                  feedMode === FEED_MODES.FOR_YOU
                    ? 'bg-gradient-to-r from-blue-600 to-brand-blue text-white shadow-md shadow-blue-500/20'
                    : 'text-gray-600 dark:text-gray-400 hover:text-gray-900 dark:hover:text-white hover:bg-gray-100/70 dark:hover:bg-white/[0.05]'
                }`}
              >
                <Compass size={14} className="shrink-0" />
                <span className="whitespace-nowrap">{t('forYou')}</span>
              </button>

              <button
                onClick={() => setFeedMode(FEED_MODES.FOLLOWING)}
                className={`flex items-center justify-center gap-1 sm:gap-1.5 px-1.5 sm:px-2.5 py-2 rounded-xl text-[11px] sm:text-xs font-bold transition-all duration-200 w-full min-w-0 ${
                  feedMode === FEED_MODES.FOLLOWING
                    ? 'bg-gradient-to-r from-blue-600 to-brand-blue text-white shadow-md shadow-blue-500/20'
                    : 'text-gray-600 dark:text-gray-400 hover:text-gray-900 dark:hover:text-white hover:bg-gray-100/70 dark:hover:bg-white/[0.05]'
                }`}
              >
                <Users size={14} className="shrink-0" />
                <span className="whitespace-nowrap">{t('following')}</span>
              </button>

              <button
                onClick={() => setFeedMode(FEED_MODES.REELS)}
                className={`flex items-center justify-center gap-1 sm:gap-1.5 px-1.5 sm:px-2.5 py-2 rounded-xl text-[11px] sm:text-xs font-bold transition-all duration-200 w-full min-w-0 ${
                  feedMode === FEED_MODES.REELS
                    ? 'bg-gradient-to-r from-blue-600 to-brand-blue text-white shadow-md shadow-blue-500/20'
                    : 'text-gray-600 dark:text-gray-400 hover:text-gray-900 dark:hover:text-white hover:bg-gray-100/70 dark:hover:bg-white/[0.05]'
                }`}
              >
                <Film size={14} className="shrink-0" />
                <span className="whitespace-nowrap">Shorts</span>
              </button>

              <button
                onClick={() => setFeedMode(FEED_MODES.COMMUNITIES)}
                className={`flex items-center justify-center gap-1 sm:gap-1.5 px-1.5 sm:px-2.5 py-2 rounded-xl text-[11px] sm:text-xs font-bold transition-all duration-200 w-full min-w-0 ${
                  feedMode === FEED_MODES.COMMUNITIES
                    ? 'bg-gradient-to-r from-blue-600 to-brand-blue text-white shadow-md shadow-blue-500/20'
                    : 'text-gray-600 dark:text-gray-400 hover:text-gray-900 dark:hover:text-white hover:bg-gray-100/70 dark:hover:bg-white/[0.05]'
                }`}
              >
                <Users size={14} className="shrink-0" />
                <span className="whitespace-nowrap">Circles</span>
              </button>

              <button
                onClick={() => setFeedMode(FEED_MODES.STUDIO)}
                className={`flex items-center justify-center gap-1 sm:gap-1.5 px-1.5 sm:px-2.5 py-2 rounded-xl text-[11px] sm:text-xs font-bold transition-all duration-200 w-full min-w-0 ${
                  feedMode === FEED_MODES.STUDIO
                    ? 'bg-gradient-to-r from-purple-600 to-brand-blue text-white shadow-md shadow-purple-500/20'
                    : 'text-gray-600 dark:text-gray-400 hover:text-gray-900 dark:hover:text-white hover:bg-gray-100/70 dark:hover:bg-white/[0.05]'
                }`}
              >
                <Building2 size={14} className="shrink-0" />
                <span className="whitespace-nowrap">Studios</span>
              </button>

              <button
                onClick={() => setFeedMode(FEED_MODES.DISCOVER)}
                className={`flex items-center justify-center gap-1 sm:gap-1.5 px-1.5 sm:px-2.5 py-2 rounded-xl text-[11px] sm:text-xs font-bold transition-all duration-200 w-full min-w-0 ${
                  feedMode === FEED_MODES.DISCOVER
                    ? 'bg-gradient-to-r from-blue-600 to-brand-blue text-white shadow-md shadow-blue-500/20'
                    : 'text-gray-600 dark:text-gray-400 hover:text-gray-900 dark:hover:text-white hover:bg-gray-100/70 dark:hover:bg-white/[0.05]'
                }`}
              >
                <Search size={14} className="shrink-0" />
                <span className="whitespace-nowrap">{t('discover')}</span>
              </button>
            </div>
          </div>

          {/* Feed Content Selection */}
          {feedMode === FEED_MODES.DISCOVER ? (
            <Discover
              user={user}
              userData={userData}
              openPublicProfile={openPublicProfile}
            />
          ) : feedMode === FEED_MODES.REELS ? (
            <ReelsFeed
              user={user}
              userData={userData}
              onOpenProfile={openPublicProfile}
            />
          ) : feedMode === FEED_MODES.COMMUNITIES ? (
            <CommunitiesSection />
          ) : loading ? (
            renderSkeleton()
          ) : (
            <>
              {/* Following tab empty state with suggestions */}
              {feedMode === FEED_MODES.FOLLOWING && followingIds.length === 0 && (
                <motion.div
                  initial={{ opacity: 0, y: 20 }}
                  animate={{ opacity: 1, y: 0 }}
                  className="bg-gradient-to-br from-blue-50 to-purple-50 dark:from-blue-900/20 dark:to-purple-900/20 rounded-2xl p-6 mb-6 border border-blue-100 dark:border-blue-800/30"
                >
                  <div className="text-center mb-6">
                    <div className="w-16 h-16 mx-auto mb-4 rounded-full bg-brand-blue/10 flex items-center justify-center">
                      <UserPlus size={28} className="text-brand-blue" />
                    </div>
                    <h3 className="text-lg font-bold dark:text-white mb-2">
                      Start following creators
                    </h3>
                    <p className="text-sm text-gray-600 dark:text-gray-400 max-w-sm mx-auto">
                      Follow artists, engineers, and studios to see their posts in your Following feed.
                    </p>
                  </div>

                  {/* Suggested users */}
                  {showSuggestedAccounts && (
                    <>
                      {loadingSuggestions ? (
                        <div className="space-y-2">
                          <h4 className="text-xs font-bold text-gray-500 uppercase tracking-wider mb-3">
                            Suggested for you
                          </h4>
                          {[1, 2, 3].map(i => (
                            <div key={i} className="flex items-center justify-between p-3 bg-white dark:bg-dark-card rounded-xl border dark:border-gray-700 animate-pulse">
                              <div className="flex items-center gap-3 flex-1">
                                <div className="h-10 w-10 rounded-full bg-gray-200 dark:bg-gray-700" />
                                <div className="flex-1 space-y-2">
                                  <div className="h-4 w-24 bg-gray-200 dark:bg-gray-700 rounded" />
                                  <div className="h-3 w-16 bg-gray-100 dark:bg-gray-800 rounded" />
                                </div>
                              </div>
                              <div className="h-8 w-20 bg-gray-200 dark:bg-gray-700 rounded-lg" />
                            </div>
                          ))}
                        </div>
                      ) : suggestedUsers.length > 0 && (
                        <div className="space-y-2">
                          <h4 className="text-xs font-bold text-gray-500 uppercase tracking-wider mb-3">
                            Suggested for you
                          </h4>
                          {suggestedUsers.map(suggestedUser => (
                            <SuggestedUserCard
                              key={suggestedUser.userId}
                              suggestedUser={suggestedUser}
                            />
                          ))}
                        </div>
                      )}
                    </>
                  )}
                </motion.div>
              )}

              {/* Posts Stream */}
              <motion.div
                variants={containerVariants}
                initial="hidden"
                animate="show"
                className="space-y-4"
              >
                <AnimatePresence mode='popLayout'>
                  {posts.map((post, index) => {
                    const shouldInjectAd = isAdEligible && activeAds.length > 0 && (index + 1) % 6 === 0;
                    const adToDisplay = shouldInjectAd ? activeAds[Math.floor(index / 6) % activeAds.length] : null;

                    return (
                      <React.Fragment key={post.id}>
                        <PostCard
                          post={post}
                          currentUser={user}
                          currentUserData={userData}
                          subProfiles={subProfiles}
                          openPublicProfile={openPublicProfile || (() => {})}
                          onReport={() => setReportTarget(post)}
                          onDelete={(postId) => {
                            console.log('Delete post:', postId);
                          }}
                          isFollowingAuthor={isFollowing(post.userId)}
                          onToggleFollow={() => { toggleFollow(post.userId); }}
                          autoPlayVideos={autoPlayVideos}
                        />
                        {adToDisplay && (
                          <SponsoredPostCard ad={adToDisplay as any} />
                        )}
                      </React.Fragment>
                    );
                  })}
                </AnimatePresence>

                {posts.length === 0 && feedMode === FEED_MODES.FOR_YOU && (
                  <motion.div
                    initial={{ opacity: 0 }}
                    animate={{ opacity: 1 }}
                    className="text-center py-10 text-gray-500"
                  >
                    <RefreshCw className="mx-auto mb-2 opacity-50" size={32} />
                    <p>{t('noPosts')}. {t('beFirst')}</p>
                  </motion.div>
                )}

                {posts.length === 0 && feedMode === FEED_MODES.STUDIO && (
                  <motion.div
                    initial={{ opacity: 0 }}
                    animate={{ opacity: 1 }}
                    className="text-center py-12 text-gray-500 bg-white dark:bg-dark-card rounded-2xl border dark:border-gray-700 p-8 shadow-sm"
                  >
                    <Building2 className="mx-auto mb-3 text-purple-500 opacity-60" size={40} />
                    <h3 className="font-bold text-sm dark:text-white mb-1">No Studio Posts Yet</h3>
                    <p className="text-xs text-gray-500 dark:text-gray-400 max-w-sm mx-auto">
                      Posts published by recording studios or creators who tag a studio will appear here in the Studios Feed.
                    </p>
                  </motion.div>
                )}

                {posts.length === 0 && feedMode === FEED_MODES.FOLLOWING && followingIds.length > 0 && (
                  <motion.div
                    initial={{ opacity: 0 }}
                    animate={{ opacity: 1 }}
                    className="text-center py-10 text-gray-500"
                  >
                    <Users className="mx-auto mb-2 opacity-50" size={32} />
                    <p>{t('noPostsFollowing')}.</p>
                    <button
                      onClick={() => setFeedMode(FEED_MODES.FOR_YOU)}
                      className="mt-3 text-brand-blue hover:underline text-sm font-medium"
                    >
                      {t('browseForYou')}
                    </button>
                  </motion.div>
                )}
              </motion.div>
            </>
          )}
        </div>

        {/* ===================================================== */}
        {/* RIGHT COLUMN: Trending Topics & News Sidebar          */}
        {/* ===================================================== */}
        <div className="hidden lg:block lg:col-span-3 space-y-4">
          {/* Boost Visibility Action Card */}
          <div className="bg-gradient-to-br from-purple-950/40 via-blue-950/30 to-gray-900/50 p-4 rounded-2xl border border-purple-500/30 shadow-md">
            <div className="flex items-center gap-1.5 text-purple-400 font-bold text-xs mb-1">
              <Sparkles size={14} /> Priority Visibility
            </div>
            <h4 className="font-black text-xs text-white">Want to reach 3x more artists?</h4>
            <p className="text-[11px] text-gray-300 mt-1">
              Get the verified creator checkmark and feed ranking priority on your music drops.
            </p>
            <button
              onClick={() => setShowBoostModal(true)}
              className="mt-3 w-full py-1.5 rounded-xl bg-gradient-to-r from-brand-blue to-purple-600 hover:opacity-95 text-white font-bold text-xs shadow-sm transition flex items-center justify-center gap-1"
            >
              <span>Increase Visibility</span>
              <ChevronRight size={14} />
            </button>
          </div>

          {/* Trending Music Topics */}
          <div className="bg-white dark:bg-dark-card rounded-2xl p-4 border dark:border-gray-700 shadow-sm">
            <h4 className="font-bold text-xs uppercase tracking-wider text-gray-500 dark:text-gray-400 mb-3 flex items-center gap-1.5">
              <TrendingUp size={16} className="text-brand-blue" /> Trending Industry News
            </h4>
            <div className="space-y-3">
              {[
                { tag: '#MixingMastering', posts: '1.4k posts', category: 'Engineering' },
                { tag: '#VocalStems', posts: '890 posts', category: 'Production' },
                { tag: '#AnalogGear', posts: '620 posts', category: 'Hardware' },
                { tag: '#IndependentArtist', posts: '2.1k posts', category: 'Career' },
              ].map((topic, i) => (
                <div key={i} className="group cursor-pointer">
                  <span className="text-xs text-gray-400 block">{topic.category}</span>
                  <h5 className="text-xs font-bold dark:text-white group-hover:text-brand-blue transition">
                    {topic.tag}
                  </h5>
                  <span className="text-[11px] text-gray-500">{topic.posts}</span>
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>

      {/* Report Modal */}
      {reportTarget && (
        <ReportModal
          user={user}
          target={{
            id: reportTarget.id,
            type: 'post',
            summary: reportTarget.text ? reportTarget.text.substring(0, 50) : 'Media Post'
          }}
          onClose={() => setReportTarget(null)}
        />
      )}

      {/* Boost Visibility Modal */}
      {showBoostModal && (
        <BoostVisibilityModal
          isOpen={showBoostModal}
          onClose={() => setShowBoostModal(false)}
          user={user}
          userData={userData}
        />
      )}
    </div>
  );
}
